import argparse,hashlib,json,os,subprocess,sys,time # Record real independent-process execution without changing any numerical verification.
from pathlib import Path # Keep each receipt beside its already registered test-history verification output.
def digest(path): return hashlib.sha256(Path(path).read_bytes()).hexdigest() # Bind small source and checkpoint artifacts to their exact bytes.
def read(path): return json.loads(Path(path).read_text()) # Read only released public identities and frozen selected-model metadata.
def atomic(path,value): # Publish complete process observations without fabricating absent execution events.
    path=Path(path);temporary=path.with_suffix(path.suffix+'.pending');payload=(json.dumps(value,indent=2,sort_keys=True)+'\n').encode() # Encode the actual observation before creating its temporary file.
    with temporary.open('wb') as stream: stream.write(payload);stream.flush();os.fsync(stream.fileno()) # Persist the original observation before its atomic name is published.
    os.replace(temporary,path);assert path.read_bytes()==payload # Verify the exact published process receipt bytes.
def main(): # Run the six already prescribed checks sequentially in six new Python processes.
    parser=argparse.ArgumentParser();parser.add_argument('--root',required=True);args=parser.parse_args();root=Path(args.root).resolve();operator=root/'operator';formal=operator/'formal';bootstrap=operator/'v2_locked_module_bootstrap.py';bootstrap_bytes=bootstrap.read_bytes();bootstrap_identity={'path':str(bootstrap),'sha256':digest(bootstrap)} # No private descriptor or model-selection argument is accepted.
    frozen=read(formal/'frozen_models.json');released=read(operator/'evaluation_native/released_index.json');assert released['status']=='NATIVE_EVALUATION_COMPLETE' # Do not verify incomplete or unqualified native slots.
    environment=dict(os.environ);environment.update(PYTHONDONTWRITEBYTECODE='1',OMP_NUM_THREADS='1',OPENBLAS_NUM_THREADS='1',MKL_NUM_THREADS='1');source=Path(__file__).resolve();source_bytes=source.read_bytes() # Match the frozen one-thread arithmetic without importing Torch in this launcher.
    for family in ('friction','rebar'): # The family and strategy order is fixed independently of observed prediction errors.
        case_id=f'v2_{family}_test_00';row=next(item for item in released['families'][family] if item['id']==case_id);assert row['quality']=='VALID_CONVERGED' # Both predesignated first test histories were independently qualified before this launcher was authored.
        assert read(formal/family/'final_test/summary.json')['status']=='FROZEN_TEST_EVALUATION_COMPLETE' # Replay only the completed official model emissions.
        for strategy in ('initial','active','random'): # Never select a checkpoint or verification history from its new-test error.
            model=frozen['families'][family][strategy];assert digest(model['path'])==model['sha256'];directory=formal/family/'final_test/invariants'/strategy;directory.mkdir(parents=True,exist_ok=True) # Bind the exact validation-selected checkpoint.
            receipt=directory/'process_execution.json';assert not receipt.exists() and not (directory/'invariants.json').exists(), 'Preserve prior invocation evidence; do not silently repeat it.' # This launcher records one actual verification process per selected model.
            snapshot=directory/'launcher_source.py';snapshot.write_bytes(source_bytes);assert snapshot.read_bytes()==source_bytes # Keep the exact nonnumerical launcher with each portable evidence package.
            prediction=formal/family/'final_test'/strategy/f'{case_id}.npz';assert prediction.is_file() # Compare against the same already published complete official field.
            argv=[sys.executable,str(operator/'v2_controller_invariants.py'),'--trainer',str(operator/'v2_operator_training.py'),'--checkpoint',model['path'],'--family',family,'--output',str(directory),'--config',str(operator/'v2_controller_config.json'),'--release',str(root/'audit/v2_test_release.json'),'--released-index',str(operator/'evaluation_native/released_index.json'),'--case-id',case_id,'--expected-prediction',str(prediction)] # Delegate all release, source and numerical checks to the unchanged frozen verifier.
            numerical_argv=argv[:];bootstrap_snapshot=directory/'bootstrap_source.py';bootstrap_snapshot.write_bytes(bootstrap_bytes);assert bootstrap_snapshot.read_bytes()==bootstrap_bytes;argv=[sys.executable,str(bootstrap),'--root',str(root),'--target','invariants','--startup-receipt',str(directory/'bootstrap_startup.json'),'--execution-receipt',str(directory/'bootstrap_execution.json'),'--',*numerical_argv[2:]] # Preserve the original verifier arguments exactly while preloading only its canonical frozen dependencies.
            observation={'schema':'bridge.v2.final_replay.process.v1','status':'INTENT','family':family,'strategy':strategy,'case_id':case_id,'argv':argv,'original_numerical_argv':numerical_argv,'bootstrap_source':bootstrap_identity,'bootstrap_snapshot':{'path':str(bootstrap_snapshot),'sha256':digest(bootstrap_snapshot)},'derived_from_original_launcher_sha256':'b99473d92680d7373ede0dcee541e78324b8d04e67514a3b0f186496678e9238','launcher_source':{'path':str(snapshot),'sha256':digest(snapshot)},'checkpoint_sha256':model['sha256'],'official_prediction_sha256':digest(prediction),'intent_utc':time.time(),'thread_environment':{key:environment[key] for key in ('OMP_NUM_THREADS','OPENBLAS_NUM_THREADS','MKL_NUM_THREADS')}};atomic(receipt,observation) # An interrupted launch remains an explicit intent rather than invented success.
            with (directory/'process.stdout.log').open('wb') as stdout,(directory/'process.stderr.log').open('wb') as stderr: # Preserve the original child output separately from its structured numerical receipt.
                started=time.monotonic();process=subprocess.Popen(argv,stdout=stdout,stderr=stderr,env=environment);observation.update(status='STARTED',pid=process.pid,started_utc=time.time());atomic(receipt,observation);returncode=process.wait() # Record the actual PID and block until that exact independent process has exited.
            observation.update(status='EXITED_ZERO' if returncode==0 else 'EXITED_NONZERO',returncode=returncode,ended_utc=time.time(),wall_seconds=time.monotonic()-started,stdout_sha256=digest(directory/'process.stdout.log'),stderr_sha256=digest(directory/'process.stderr.log')) # Use only observed process completion and output bytes.
            for name in ('bootstrap_startup.json','bootstrap_execution.json'): # Preserve both startup and original-script execution receipts from this actual child.
                if (directory/name).exists(): observation[name]={'path':str(directory/name),'sha256':digest(directory/name)} # Record actual child-produced module and execution identities even after a failed verifier.
            if (directory/'invariants.json').exists(): observation['invariant_receipt_sha256']=digest(directory/'invariants.json') # A failed process is never credited with a missing numerical verification.
            atomic(receipt,observation);print(json.dumps({'family':family,'strategy':strategy,'returncode':returncode,'wall_seconds':observation['wall_seconds']}),flush=True);assert returncode==0 # Stop at a genuine failure without silently rerunning or altering any field.
if __name__=='__main__': main() # Importing the launcher cannot read a new test response or start a verification process.
